class Solution {
public:
    long long kSum(vector<int>& nums, int k) {
        long long maxSum = 0;
        for (int x : nums) {
            if (x > 0) maxSum += x;
        }

        vector<long long> a;
        for (int x : nums) {
            a.push_back(abs((long long)x));
        }
        sort(a.begin(), a.end());

        int n = (int)a.size();

        priority_queue<pair<long long,int>, vector<pair<long long,int>>, greater<>> pq;
        pq.push({a[0], 1});

        long long smallest = 0;

        for (int i = 0; i < k - 1; i++) {
            auto [sum, idx] = pq.top();
            pq.pop();
            smallest = sum;

            if (idx < n) {
                pq.push({sum + a[idx], idx + 1});
                pq.push({sum - a[idx - 1] + a[idx], idx + 1});
            }
        }

        return maxSum - smallest;
    }
};
